class Solution {
public:
    vector<string> cellsInRange(string s) {
        vector<string> res;
        char c1 = s[0], c2 = s[3];
        char r1 = s[1], r2 = s[4];
        for (char c = c1; c <= c2; ++c) {
            for (char r = r1; r <= r2; ++r) {
                string cell;
                cell += c;
                cell += r;
                res.push_back(cell);
            }
        }
        return res;
    }
};
